export class PlatformUsersResource {
  private readonly core: Core;
  readonly access: PlatformUsersAccessResource;
  readonly claims: PlatformUsersClaimsResource;
  readonly passes: PlatformUsersPassesResource;
  readonly roles: PlatformUsersRolesResource;
  readonly sessions: PlatformUsersSessionsResource;
  constructor(core: Core) {
    this.core = core;
    this.access = new PlatformUsersAccessResource(core);
    this.claims = new PlatformUsersClaimsResource(core);
    this.passes = new PlatformUsersPassesResource(core);
    this.roles = new PlatformUsersRolesResource(core);
    this.sessions = new PlatformUsersSessionsResource(core);
  }

  /** List users `GET /api/v1/users` */
  list(query?: PlatformUsersListQuery, options?: RequestOptions): PagePromise<PlatformUsersListResult> {
    return this.core.paginate({ method: 'GET', path: '/api/v1/users', query }, 'cursor', options);
  }

  /** Offboard a user: end their memberships, developer sponsorships, platform grants and keys, sign them out and disable them, then take their Polaris ID roles away. `dryRun` answers 200 with the plan and changes nothing. Otherwise 202 with the plan and an operation (`idp.offboard`). 409 `IDP_PLATFORM_ADMIN` for a platform admin, `LAST_ORG_ADMIN` when an org would lose its last admin. `POST /api/v1/users/{id}/offboard` */
  offboard(id: string, body?: PlatformUsersOffboardBody, options?: RequestOptions): Promise<PlatformUsersOffboardResult> {
    return this.core.request({ method: 'POST', path: `/api/v1/users/${encodeURIComponent(id)}/offboard`, body }, options);
  }

  /** Get a user `GET /api/v1/users/{id}` */
  retrieve(id: string, options?: RequestOptions): Promise<PlatformUsersRetrieveResult> {
    return this.core.request({ method: 'GET', path: `/api/v1/users/${encodeURIComponent(id)}` }, options);
  }

  /** Disable or enable a user `PATCH /api/v1/users/{id}` */
  update(id: string, body: PlatformUsersUpdateBody, options?: RequestOptions): Promise<PlatformUsersUpdateResult> {
    return this.core.request({ method: 'PATCH', path: `/api/v1/users/${encodeURIComponent(id)}`, body }, options);
  }
}

